<script setup lang="ts">
type Product = {
  id: string
  slug: string
  name: string
  kind: 'EXTENSION' | 'WIG'
  texture?: string
  image: string
  description: string
  variants: Array<{ sku: string, color: string, length: number, price: number, stock: number }>
}

const type = ref<'ALL' | 'EXTENSION' | 'WIG'>('ALL')
const texture = ref('ALL')
const length = ref('ALL')
const filters = computed(() => ({ ...(type.value !== 'ALL' ? { type: type.value } : {}), ...(texture.value !== 'ALL' ? { texture: texture.value } : {}), ...(length.value !== 'ALL' ? { length: length.value } : {}) }))
const config = useRuntimeConfig()
const { data: products, pending } = await useAsyncData<Product[]>('catalog', () => $fetch(`${config.public.apiBase}/api/catalog`, { query: filters.value }), { watch: [filters] })
const minPrice = (product: Product) => Math.min(...product.variants.map(variant => variant.price))
const colors = (product: Product) => [...new Set(product.variants.map(variant => variant.color))]
const colorStyle = (color: string) => ({ 'Negro natural': '#171717', 'Castaño oscuro': '#513725', Chocolate: '#83553c' }[color] || '#d5c39b')
</script>

<template>
  <main class="shop-page">
    <section class="shop-intro"><div class="page-shell"><p class="shop-kicker">Tienda · Cabello humano natural virgen</p><div><h1>Elige tu <em>textura.</em></h1><p>Extensiones de 10″ a 30″ y pelucas seleccionadas para que encuentres tu look.</p></div></div></section>
    <section class="shop-content page-shell"><aside class="filters"><div class="filters-heading"><span>Filtros</span><button type="button" @click="type = 'ALL'; texture = 'ALL'; length = 'ALL'">Limpiar</button></div><div><p class="filter-label">Producto</p><div class="filter-options"><button v-for="option in [{ label: 'Todo', value: 'ALL' }, { label: 'Extensiones', value: 'EXTENSION' }, { label: 'Pelucas', value: 'WIG' }]" :key="option.value" :class="{ active: type === option.value }" @click="type = option.value as typeof type">{{ option.label }}</button></div></div><div v-if="type !== 'WIG'"><p class="filter-label">Textura</p><div class="filter-options"><button v-for="option in ['ALL', 'Liso', 'Ondulado', 'Rizado', 'Crespo']" :key="option" :class="{ active: texture === option }" @click="texture = option">{{ option === 'ALL' ? 'Todas' : option }}</button></div></div><div><p class="filter-label">Longitud</p><div class="length-filter"><button v-for="option in ['ALL', '10', '14', '20', '30']" :key="option" :class="{ active: length === option }" @click="length = option">{{ option === 'ALL' ? 'Todas' : `${option}″` }}</button></div></div></aside>
      <div class="products-area"><div class="catalog-meta"><p><b>{{ products?.length || 0 }}</b> productos encontrados</p><p>Envíos a todo Ecuador</p></div><div v-if="pending" class="loading">Cargando colección…</div><div v-else class="product-grid"><article v-for="product in products" :key="product.id" class="product-card"><NuxtLink :to="`/tienda/${product.slug}`" class="product-link"><div class="product-photo"><span class="texture-badge">{{ product.kind === 'EXTENSION' ? product.texture : 'Peluca' }}</span><img :src="product.image" :alt="product.name"></div><div class="product-copy"><p class="product-type">{{ product.kind === 'EXTENSION' ? 'Extensión · Cabello humano' : 'Peluca · Cabello humano' }}</p><h2>{{ product.name }}</h2><div class="swatches"><span v-for="color in colors(product)" :key="color" :style="{ background: colorStyle(color) }" :title="color" /></div><p class="options">{{ product.variants.length }} opciones · {{ [...new Set(product.variants.map(item => item.length))].join('″ · ') }}″</p><div class="price-row"><strong>Desde ${{ minPrice(product).toFixed(2) }}</strong><span>Ver producto <b>→</b></span></div></div></NuxtLink></article></div><p v-if="!pending && !products?.length" class="empty">No encontramos productos con estos filtros.</p></div>
    </section>
  </main>
</template>

